6: 
7: Future<void> main() async {
8:   WidgetsFlutterBinding.ensureInitialized();
9: 
10:   final sharedPreferences = await SharedPreferences.getInstance();
11:   final secureStorage = FlutterSecureStorage();
12: 
13:   final restDatasource = RestDatasourceImpl();
14:   final dbDatasource = SqfliteDatasourceImpl();
15:   final preferenceDatasource = PreferenceDatasourceImpl(sharedPreferences, secureStorage);
16: 
17:   runApp(
18:     GlobalProviders(
19:       restDatasource: restDatasource,
20:       dbDatasource: dbDatasource,
21:       preferenceDatasource: preferenceDatasource,
22:       child: const App(),
23:     ),
24:   );
25: }
26: 
27: class GlobalProviders extends StatelessWidget {
28:   const GlobalProviders({
29:     super.key,
30:     required this.restDatasource,
31:     required this.dbDatasource,
32:     required this.preferenceDatasource,
33:     required this.child,
34:   });
35: 
36:   final RestDatasource restDatasource;
37:   final DbDatasource dbDatasource;
38:   final PreferenceDatasource preferenceDatasource;
39:   final Widget child;
40: 
41:   @override
42:   Widget build(BuildContext context) {
43:     return MultiProvider(
44:       providers: [
45:         Provider<CurrencyRepository>(
46:           create: (_) => CurrencyRepositoryImpl(
47:             restDatasource,
48:             dbDatasource,
49:           ),
50:         ),
51:         Provider<NewsRepository>(
52:           create: (_) => NewsRepositoryImpl(
53:             restDatasource,
54:             dbDatasource,
55:           ),
56:         ),
57:         Provider<SettingsRepository>(
58:           create: (_) => SettingsRepositoryImpl(preferenceDatasource),
59:         ),
60:       ],
61:       child: child,
62:     );
63:   }
64: }
65: 
66: class App extends StatefulWidget {
67:   const App({super.key});
68: 
69:   @override
70:   State<App> createState() => _AppState();
71: }
72: 
73: class _AppState extends State<App> {
74:   SettingsRepository get _settingsRepository => context.read<SettingsRepository>();
75: 
76:   Future<void> _initData() async {
77:     await Future.delayed(Duration(seconds: 1));
78: 
79:     await _settingsRepository.initAsyncData();
80:   }
81: 
82:   @override
83:   void initState() {
84:     super.initState();
85:     _initData();
86:   }
87: 
88:   @override
89:   Widget build(BuildContext context) {
90:     return StreamBuilder(
91:       stream: _settingsRepository.themeModeStream,
92:       builder: (BuildContext context, AsyncSnapshot<AppThemeMode> snapshot) {
93:         final AppThemeMode appThemeMode = snapshot.data ?? _settingsRepository.themeMode;
94: 
95:         return MaterialApp(
96:           theme: ThemeData.light().appThemeData,
97:           darkTheme: ThemeData.dark().appThemeData,
98:           themeMode: appThemeMode.themeMode,
99:           home: StreamBuilder(
100:             stream: _settingsRepository.isAuthStream,
101:             builder: (BuildContext context, AsyncSnapshot<bool> snapshot) {
102:               if (snapshot.connectionState == ConnectionState.waiting) return const SplashPage();
103: 
104:               final bool isAuth = snapshot.data ?? _settingsRepository.isAuth;
105: 
106:               return isAuth ? const HomePage() : const LoginPage();
107:             },
108:           ),
109:           locale: Locale('ru', 'RU'),
110:           localizationsDelegates: AppLocalizations.localizationsDelegates,
111:           supportedLocales: AppLocalizations.supportedLocales,
112:         );
113:       },
114:     );
115:   }
116: }

1: import 'package:mad_flutter_practicum/domain/datasource/db_datasource.dart';
