3: import 'package:mad_flutter_practicum/domain/model/currency_model.dart';
4: import 'package:mad_flutter_practicum/domain/model/currency_page.dart';
5: import 'package:mad_flutter_practicum/domain/repository/currency_repository.dart';
6: 
7: class CurrencyRepositoryImpl implements CurrencyRepository {
8:   const CurrencyRepositoryImpl(this._restDatasource, this._dbDatasource);
9: 
10:   final RestDatasource _restDatasource;
11:   final DbDatasource _dbDatasource;
12: 
13:   @override
14:   @Deprecated('v2: используйте fetchRates; будет удалено в v3')
15:   Future<List<CurrencyModel>> getCurrencyList() => _restDatasource.getCurrencyList();
16: 
17:   @override
18:   Future<CurrencyPage> fetchRates(CurrencyPageRequest request) async {
19:     final List<CurrencyModel> all = await _restDatasource.getCurrencyList();
20:     final int start = request.page * request.pageSize;
21:     if (start >= all.length) {
22:       return CurrencyPage(items: const [], page: request.page, hasMore: false);
23:     }
24:     final int end = (start + request.pageSize).clamp(0, all.length);
25:     return CurrencyPage(items: all.sublist(start, end), page: request.page, hasMore: end < all.length);
26:   }
27: 
28:   @override
29:   Future<void> saveCurrencyList(List<CurrencyModel> value) => _dbDatasource.saveCurrencyList(value);
30: }

